              ";\n\nfunction toTime(ts) {\n    const d = new Date(ts * 1000);\n    const y = d.getFullYear();\n    const m = String(d.getMonth() + 1).padStart(2, '0');\n    const day = String(d.getDate()).padStart(2, '0');\n    const h = String(d.getHours()).padStart(2, '0');\n    const min = String(d.getMinutes()).padStart(2, '0');\n    return y + '-' + m + '-' + day + ' ' + h + ':' + min;\n}\n\nfunction formatDelta(num) {\n    if (!num) return '';\n    return num > 0 ? '<span class=\"tag-pos\">+' + num + '</span>' : '<span class=\"tag-neg\">' + num + '</span>';\n}\n\nfunction buildSummary(records) {\n    let ybIn = 0, ybOut = 0;\n    let bindYbIn = 0;\n    let ybFromGoods = 0;\n    let yuxiFromGoods = 0;\n    let yuxiSpend = 0;\n    records.forEach(r => {\n        if (r.currency) {\n            const yb = Number(r.currency.yuanbao || 0);\n            if (yb > 0) ybIn += yb; else ybOut += yb;\n        }\n        if (r.items) {\n            r.items.forEach(i => {\n                const name = i.name || '';\n                const count = Number(i.count || 0);\n                if (name.includes('绑定元宝')) bindYbIn += count;\n                else if (name.includes('元宝')) ybFromGoods += count;\n                if (name.includes('玉玺')) {\n                    if (count > 0) yuxiFromGoods += count;\n                    else if (count < 0) yuxiSpend += Math.abs(count);\n                }\n            });\n        }\n    });\n    const total = records.length;\n    const incomeValue = ybIn + ybFromGoods + bindYbIn;\n    \n    // Helper to make cards\n    const card = (label, val, isNeg) =>\n        '<div class=\"stat-card\">' +\n        '<div class=\"stat-label\">' + label + '</div>' +\n        '<div class=\"stat-value\" style=\"' + (isNeg ? 'color: var(--danger)' : '') + '\">' + val + '</div>' +\n        '</div>';\n\n    return [\n        card('总记录数', total),\n        card('元宝收入', incomeValue),\n        card('元宝支出', Math.abs(ybOut), true),\n        card('玉玺收入', yuxiFromGoods),\n        card('玉玺支出', yuxiSpend, true)\n    ].join('');\n}\n\nfunction applyFilter(useFilter) {\n    let start = (document.getElementById('start').valueAsNumber || 0) / 1000;\n    let end = (document.getElementById('end').valueAsNumber || Infinity) / 1000;\n    if (start > end) [start, end] = [end, start];\n    end += 24 * 60 * 60;\n    const kw = (document.getElementById('search').value || '').trim();\n    const eventType = document.getElementById('eventType').value;\n\n    let records = data.slice();\n    if (useFilter) {\n        records = records.filter(r => {\n            if (r.ts < start || r.ts >= end) return false;\n            const rType = r.eventType || r.kind || 'unknown';\n            if (eventType !== 'all' && rType !== eventType) return false;\n            if (!kw) return true;\n            const text = [\n                r.typeName || '',\n                r.reasonName || '',\n                ...(r.items || []).map(i => i.name),\n                ...(r.purchase?.items || []).map(i => i.name)\n            ].join(' ');\n            return text.includes(kw);\n        });\n    }\n\n    document.getElementById('summary').innerHTML = buildSummary(records);\n    renderPurchaseTable(records);\n    renderGoodsTotalTable(records);\n    renderDetailTable(records);\n}\n\nfunction renderPurchaseTable(records) {\n    const map = {};\n    records.forEach(r => {\n        const purchase = r.purchase;\n        if (!purchase || !purchase.items) return;\n        purchase.items.forEach(item => {\n            const name = item.name || String(item.id || '');\n            if (!map[name]) map[name] = {times: 0, total: 0, spend: 0};\n            map[name].times += 1;\n            map[name].total += Number(item.count || 0);\n            const price = Number(item.priceYuanBao || 0);\n            if (price > 0) map[name].spend += price;\n            else if (purchase.totalPriceYuanBao && purchase.items.length === 1) map[name].spend += purchase.totalPriceYuanBao;\n        });\n    });\n    const rows = Object.entries(map).map(([name, info]) => {\n        return '<tr><td>' + name + '</td><td class=\"text-right\">' + info.times + '</td><td class=\"text-right\">' + info.total + '</td></tr>';\n    }).join('');\n    document.querySelector('#purchaseTable tbody').innerHTML = rows || '<tr><td colspan=\"3\" class=\"muted text-center\" style=\"text-align:center\">暂无购买记录</td></tr>';\n}\n\nfunction renderGoodsTotalTable(records) {\n    const map = {};\n    records.forEach(r => {\n        (r.items || []).forEach(item => {\n            const count = Number(item.count || 0);\n            if (count <= 0) return;\n            const key = item.id || item.name || '';\n            const name = item.name || String(item.id || '');\n            if (!map[key]) map[key] = {name, times: 0, total: 0};\n            map[key].times += 1;\n            map[key].total += count;\n        });\n    });\n    const rows = Object.values(map)\n        .sort((a, b) => b.total - a.total || a.name.localeCompare(b.name, 'zh-CN'))\n        .map(info => '<tr><td>' + info.name + '</td><td class=\"text-right\">' + info.times + '</td><td class=\"text-right\">' + info.total + '</td></tr>')\n        .join('');\n    document.querySelector('#goodsTotalTable tbody').innerHTML = rows || '<tr><td colspan=\"3\" class=\"muted text-center\" style=\"text-align:center\">暂无物品获得记录</td></tr>';\n}\n\nfunction renderDetailTable(records) {\n    const rows = records.slice().reverse().map(r => {\n        const fmtItem = (name, count) =>\n            '<span class=\"item-pill\">' + name + ' <span class=\"item-count\">x' + count + '</span></span>';\n        \n        const itemText = (r.items || []).map(i => fmtItem(i.name, i.count)).join(' ') || '<span class=\"muted\">-</span>';\n        const purchaseText = r.purchase?.items?.length\n            ? '购买: ' + r.purchase.items.map(i => fmtItem(i.name, i.count)).join(' ')\n            : '';\n        const costText = r.purchase?.costItems?.length\n            ? '消耗: ' + r.purchase.costItems.map(i => fmtItem(i.name, i.count)).join(' ')\n            : '';\n            \n        let fullItemText = itemText;\n        if (purchaseText) {\n             fullItemText = itemText === '<span class=\"muted\">-</span>' ? purchaseText : (itemText + '<br>' + purchaseText);\n        }\n        if (costText) {\n             fullItemText = fullItemText === '<span class=\"muted\">-</span>' ? costText : (fullItemText + '<br>' + costText);\n        }\n\n        let currencyText = '<span class=\"muted\">-</span>';\n        if (r.currency) {\n            const parts = [];\n            if (r.currency.yuanbao) parts.push(formatDelta(r.currency.yuanbao));\n            currencyText = parts.length ? parts.join(' ') : currencyText;\n        }\n        const label = r.reasonName ? (r.typeName + ' · ' + r.reasonName) : (r.typeName || '未知');\n        return '<tr><td>' + toTime(r.ts) + '</td><td>' + label + '</td><td>' + fullItemText + '</td><td class=\"text-right\">' + currencyText + '</td></tr>';\n    }).join('');\n    document.querySelector('#detailTable tbody').innerHTML = rows || '<tr><td colspan=\"4\" class=\"muted text-center\" style=\"text-align:center; padding: 30px;\">暂无相关数据</td></tr>';\n}\n\n// Initialize\nconst nav = document.querySelector('.nav');\nif (nav) {\n    const offset = nav.offsetHeight + 16;\n    document.documentElement.style.setProperty('--nav-offset', offset + 'px');\n}\nconst endInput = document.getElementById('end');\nconst startInput = document.getElementById('start');\nconst today = new Date();\nconst lastWeek = new Date(today.getTime() - 7 * 86400000);\nif (endInput) endInput.valueAsDate = today;\nif (startInput) startInput.valueAsDate = lastWeek;\napplyFilter(false);\n</script>\n</body>\n</html>",
