        appendLocalSkinDebugLine(
          "respHook: 皮肤响应 cn=" +
            cn +
            " gid=" +
            state.pendingSkin.generalID +
            " sid=" +
            state.pendingSkin.skinID +
            " age=" +
            age +
            "ms",
        );
